from io import BytesIO

encoded_data = b'hello\\rworld'
checksum = hashlib.sha1(encoded_data).hexdigest().encode('ascii')
stream = BytesIO(
    str(len(encoded_data)).encode('ascii') + b'\n' +
    encoded_data + checksum + b'\n'
)

assert read_stream(stream) == b'hello\rworld'

incomplete_stream = BytesIO(b'10\nabc')
try:
    read_stream(incomplete_stream)
except Exception as exc:
    assert str(exc) == "EOF found before data was complete"
else:
    raise AssertionError("Expected incomplete data to raise an exception")

